mapper.select:
SELECT MAX(ML.YYYYMM)
FROM   MATERIAL_INV_BAL ML
WHERE  ML.YYYYMM <= #{uptoYyyyMm}
AND    ML.ITEM_CODE = #{itemCode}
AND    ML.DIVISION_CODE = #{divisionCode}
AND    ML.COMPANY_CODE = #{companyCode}
AND    ML.INPUT_QTY > 0

SELECT COUNT(*)                          AS poCount
      ,COALESCE(SUM(PL.WAREHOUSING_AMOUNT), 0) AS warehousingAmountSum
FROM   PO_LEDGER PL
WHERE  PL.ITEM_CODE = #{itemCode}
AND    PL.COMPANY_CODE = #{companyCode}
AND    PL.WAREHOUSING_DATE BETWEEN #{fromDate} AND #{toDate}
